const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=Object.fromEntries(E.SKILL_TREE_DEFINITION.nodes.map(n=>[n.id,n.name]));
export const DISPLAY_COLORS={physical:'#fff0d0',fire:'#ff9b54',earth:'#d3b77f',water:'#74c9ef',wind:'#a6e1be',light:'#fff5a9',dark:'#bf9cfa',poison:'#bded65',heal:'#8eed9a',shield:'#8bd8f3'};
export function createBattleSliceModel({now=Date.now(),state=null,scenario='fire',seed=scenario==='poison'?13:24}={}){let rng=seed>>>0;const run=(fn,at=now)=>{const random=Math.random,clock=Date.now;Math.random=()=>{rng=(Math.imul(rng,1664525)+1013904223)>>>0;return rng/4294967296;};Date.now=()=>at;try{return fn();}finally{Math.random=random;Date.now=clock;}};
 const s=state?structuredClone(state):run(()=>E.fresh());if(!state){const afterFreshRng=rng;let weapon=s.inventory.find(it=>it.id===s.equip.weapon);for(let attempt=0;weapon.weaponType!=='axe'&&attempt<64;attempt++)weapon=run(()=>E.item('weapon',1,null,0));if(weapon.weaponType!=='axe')throw Error('隔离斧模板未就绪');const oldWeapon=s.equip.weapon;s.inventory=s.inventory.filter(it=>it.id!==oldWeapon);s.inventory.push(weapon);s.equip.weapon=weapon.id;rng=afterFreshRng;s.level=20;const p=s.skillTree.presets[0];p.unlocked=['fracture_strike','ember_brand','iron_vigil','forge_breath','mountain_vitality','forged_resilience'];p.active=['iron_vigil','ember_brand','fracture_strike','forge_breath'];p.passive=['mountain_vitality','forged_resilience'];p.conditions=['always','always','always','low'];s.potionStacks={'healing|0':3};E.equipPotion(s,'healing|0');E.normalizeHealth(s,now);s.heroHp=E.stats(s).hp*.35;if(scenario==='eruption'){s.level=30;p.unlocked=['fracture_strike','ember_brand','furnace_wave','iron_vigil','mountain_vitality','forged_resilience'];p.active=['furnace_wave','ember_brand','fracture_strike','iron_vigil'];p.conditions=['always','always','always','always'];}if(scenario==='poison'){s.level=30;p.unlocked=['fracture_strike','ember_brand','scatter_ash','iron_vigil','mountain_vitality','forged_resilience'];p.active=['scatter_ash','ember_brand','fracture_strike','iron_vigil'];p.conditions=['always','always','always','always'];}}
 const encounter=s.activeEncounter&&!s.activeEncounter.done?s.activeEncounter:run(()=>E.startInstanceEncounter(s,'dwarf.a01.field',now));if(!encounter)throw Error('无法建立隔离战斗');E.setMultiPaused(s,true,now);const queue=createCombatDisplayQueue();queue.beginBattle(encounter.id);let logs=[],emissionError=null;
 const publish=events=>{const result=queue.emitBatch(events);if(!result.ok)emissionError=result.reason;};
 return {fixture:{seed,initialClock:now,scenario,injuredStart:!state,description:'固定种子的真实A01遭遇；隔离角色初始35%生命演示恢复，非正常新档/产率'},get state(){return s;},get encounter(){return encounter;},get logs(){return [...logs];},get emissionError(){return emissionError;},toggle(at){if(encounter.done)return false;return E.setMultiPaused(s,!!s.running,at);},advance(at){if(!s.running||encounter.done)return [];const batch=captureCombatDisplay(encounter,()=>run(()=>E.step(s,encounter,at),at));logs=[...batch.result,...logs].slice(0,30);publish(batch.events);if(encounter.done)s.running=false;return queue.consume();},select(id){return E.setCombatTarget(s,id);},drink(at){const batch=captureCombatDisplay(encounter,()=>run(()=>E.drinkPotion(s,undefined,at,encounter),at));publish(batch.events);return {used:batch.result,events:queue.consume()};},dispose(){queue.resetSession();}};
}

export const COMBAT_GLYPHS=Object.freeze({
 fire:['00100','01100','01110','11011','11111'],
 water:['00100','01110','01110','11011','01110'],
 earth:['00100','01110','11011','11111','10001'],
 wind:['01110','00001','11110','10000','01110'],
 light:['00100','10101','01110','10101','00100'],
 dark:['01110','11000','11000','11000','01110'],
 poison:['01110','10101','11111','01110','01010'],
 heal:['00100','00100','11111','00100','00100'],
 shield:['11111','10001','10101','01110','00100']
});
export function drawCombatGlyph(c,kind,x,y,color){const rows=COMBAT_GLYPHS[kind];if(!rows)return;const points=[];rows.forEach((r,dy)=>[...r].forEach((v,dx)=>{if(v==='1')points.push([Math.round(x)+dx,Math.round(y)+dy]);}));c.fillStyle='#12151b';for(const [px,py]of points)c.fillRect(px-1,py-1,3,3);c.fillStyle=color;for(const [px,py]of points)c.fillRect(px,py,1,1);}
export function drawCombatFloat(c,f,x,y){const text=f.text,glyph=COMBAT_GLYPHS[f.glyph]?f.glyph:null;const width=c.measureText(text).width,total=width+(glyph?8:0),left=x-total/2;c.textAlign='left';c.strokeStyle='#12151b';c.strokeText(text,left,y);c.fillStyle=f.color;c.fillText(text,left,y);if(glyph)drawCombatGlyph(c,glyph,left+width+3,y-6,f.color);}

// Preserve real fractional recovery instead of displaying a successful heal as +0.
// This is presentation only: HP, lifesteal rates, caps and saved values stay untouched.
export function combatDeltaLabel(value){const magnitude=Math.abs(value);return magnitude<.01?'<0.01':magnitude<1?String(Number(magnitude.toFixed(2))):String(Math.round(magnitude));}
export function displayTokens(event){if(event.kind==='cast')return [];if(event.outcome==='miss')return [{text:'闪避',color:'#b7bec5',crit:false}];const tokens=[];if(event.hpDelta<0)tokens.push({text:'−'+combatDeltaLabel(event.hpDelta),color:DISPLAY_COLORS[event.kind==='poison'?'poison':event.element]??DISPLAY_COLORS.physical,crit:event.crit,tag:'',glyph:event.kind==='poison'?'poison':COMBAT_GLYPHS[event.element]?event.element:null});if(event.hpDelta>0)tokens.push({text:'+'+combatDeltaLabel(event.hpDelta),color:DISPLAY_COLORS.heal,crit:false,glyph:'heal'});if(event.shieldDelta!==0&&Number.isFinite(event.shieldDelta))tokens.push({text:(event.shieldDelta>0?'+':'−')+combatDeltaLabel(event.shieldDelta),color:DISPLAY_COLORS.shield,crit:false,tag:'',glyph:'shield'});return tokens;}
export function slicePositions(e){const enemies=e.enemies??[],xs=enemies.length===1?[350]:enemies.length===2?[315,405]:[280,355,425];return Object.fromEntries([['hero',{x:110,y:203,sprite:'dwarf'}],...enemies.map((u,i)=>[u.id,{x:xs[i]??425,y:203,sprite:i%2?'golem':'lizard'}])]);}
function skillButtons(s,e){const p=s.skillTree.presets[s.skillTree.selectedPreset];return [...p.active.map((id,i)=>({id,index:i,passive:false})),...p.passive.map((id,i)=>({id,index:i,passive:true}))].map(({id,index,passive})=>`<button class="sliceSkill ${passive?'passive':''}" data-slice-skill="${esc(id||'')}" title="${esc(names[id]||'空槽')}">${renderSkillPixelIcon(id)}<span>${esc(names[id]||'空槽')}</span>${!passive&&(e.treeSkillCooldowns?.[id]??e.cd?.[id]??0)>0?`<b class="sliceCd">${Math.ceil(e.treeSkillCooldowns?.[id]??e.cd?.[id]??0)+'回'}</b>`:''}</button>`).join('');}
export function renderSliceShell(model){return `<div class="sliceShell"><header class="sliceHeader"><h1>黑炉 · 山道交锋</h1><small>战斗画面试作 · 隔离角色<br>不读取或写入正式存档</small></header><section class="sliceStage"><canvas id="sliceCanvas" width="480" height="270" aria-label="原创像素战斗场景"></canvas><div id="sliceUnits"></div><div class="sliceFloats" id="sliceFloats"></div><div class="sliceStatus" id="sliceStatus">已暂停</div></section><section class="sliceHud"><div class="sliceSkills" id="sliceSkills">${skillButtons(model.state,model.encounter)}</div><div class="sliceActions"><button class="primary" data-slice-action="toggle">${icon('sword')}<span id="sliceRunLabel">开始</span></button><button data-slice-action="potion">${E.parsePotionKey(model.state.potionSlot?.key)?.type?potionIcon(E.parsePotionKey(model.state.potionSlot.key).type,{size:32}):'<span aria-hidden="true">+</span>'}<span class="slicePotionType">${esc(E.POTIONS[E.parsePotionKey(model.state.potionSlot?.key)?.type]?.name||'未携带')}</span><span id="slicePotionCount">药剂</span></button><button data-slice-action="restart">${icon('forge')}<span>重开</span></button><button data-slice-action="log">${icon('book')}<span>战报</span></button><button data-slice-action="record" title="录制场景与飘字，不含外围HUD">${icon('book')}<span>录制场景</span></button></div></section><div class="sliceFooter"><span>Lv.${model.state.level} 受伤试作 · 种子${model.fixture.seed}三敌 · 外观替身</span><span id="sliceOutcome">点击敌人切换目标 · 固定随机种子试作</span></div><div class="sliceHelp" id="sliceHelp" hidden></div><div class="sliceLog" id="sliceLog" hidden></div></div>`;}
// Explicit production IDs only. Utility visuals follow actual shield/heal targets, not cast's selected enemy.
export function skillVisualForEvent(event,weaponType=null){
 if(event.skillId==='scatter_ash'&&event.kind==='hit')return 'ash'; // Attempt visual, not a claim that poison/debuff landed.
 if(event.outcome==='miss')return null;
 if(event.kind==='poison')return 'poison';
 if(event.skillId==='iron_vigil'&&event.kind==='shield'&&event.shieldDelta>0)return 'shieldRune';
 if(event.skillId==='forge_breath'&&event.kind==='heal'&&event.hpDelta>0)return 'healing';
 const meta=getSkillMetadata(event.skillId);if(meta){if(event.kind==='shield'&&event.shieldDelta>0)return 'shieldRune';if(event.kind==='heal'&&event.hpDelta>0)return 'healing';if(event.kind==='hit'||event.kind==='dot'){if(meta.visual)return meta.visual;if(event.skillId.startsWith('elf.'))return weaponType==='bow'?'arrowVolley':'crystalPulse';if(event.skillId.startsWith('human.'))return meta.branch==='bleed'?'bleedArc':meta.branch==='guard'?'hammerCrack':'axeHeavy';if(event.skillId.startsWith('goblin.'))return meta.branch==='trap'||meta.branch==='contraption'?'trapSnap':'shadowCut';if(event.skillId.startsWith('ashen.'))return meta.branch==='heat'?'eruption':meta.branch==='shell'?'hammerCrack':'crystalPulse';}}
 if(event.kind!=='hit'&&event.kind!=='dot')return null;
 if(event.skillId==='fracture_strike'&&event.kind==='hit')return weaponType==='axe'?(event.segmentIndex>0?'axeHeavy':'axeFirst'):weaponType==='hammer'?'hammerCrack':null;
 if(event.skillId==='furnace_wave'&&event.kind==='hit')return 'eruption';
 if(event.skillId==='ember_brand')return event.kind==='dot'?'emberTick':'emberSeal';
 return null;
}
export function sliceActorMetadata(state){return {hero:{weaponType:state.inventory.find(it=>it.id===state.equip.weapon)?.weaponType??null}};}
function drawSkillEffects(c,effects,positions,time,reduced){
 const px=(x,y,w=3,h=w)=>c.fillRect(Math.round(x),Math.round(y),w,h);
 for(const f of effects){const p=positions[f.targetId],age=time-f.at;if(!p||age<0||age>650)continue;const t=age/650,x=p.x,y=p.y;c.save();c.globalAlpha=Math.min(1,(1-t)*2);const drift=reduced?0:t;
 if(['arrowVolley','crystalPulse','bleedArc','shadowCut','trapSnap'].includes(f.visual)){
  const color={arrowVolley:'#c7e6aa',crystalPulse:'#b5dff5',bleedArc:'#dc6475',shadowCut:'#b0b181',trapSnap:'#e4b66b'}[f.visual];c.fillStyle=color;
  if(f.visual==='arrowVolley'){for(let n=0;n<3;n++){const xx=x-70+Math.min(1,t*3)*70,yy=y-65+n*11;px(xx-26,yy,28,2);px(xx,yy-3,5,8);px(xx-23,yy-4,3,9);}}
  else if(f.visual==='crystalPulse'){for(let n=0;n<6;n++){const a=n*Math.PI/3+t*1.6,rr=14+t*36;px(x+Math.cos(a)*rr,y-55+Math.sin(a)*rr,4,8);}for(let n=-2;n<=2;n++)px(x+n*5,y-55-Math.abs(n)*4,4,8);}
  else if(f.visual==='trapSnap'){for(let n=0;n<7;n++){px(x-24+n*8,y-6,5,4);px(x-24+n*8,y-10-12*(1-t),3,10);}px(x-22,y-3,46,3);}
  else{for(let n=0;n<16;n++){const a=-1.2+n*.16,rr=18+t*12;px(x+Math.cos(a)*rr-12,y-58+Math.sin(a)*rr,5,3);}if(f.visual==='bleedArc')for(let n=0;n<5;n++)px(x-10+n*6,y-40+t*24+n%2*5,3,4);}
 }
 else if(f.visual==='axeFirst'||f.visual==='axeHeavy'){const heavy=f.visual==='axeHeavy';c.fillStyle=heavy?'#ffe7a3':'#d9edf4';for(let i=0;i<15;i++){const a=(-1.3+i*.15)*(heavy?-1:1),r=heavy?36:25;px(x+Math.cos(a)*r-12,y-56+Math.sin(a)*r,heavy?6:3,heavy?4:3);}if(heavy){c.fillStyle='#fff8dd';for(let i=0;i<5;i++)px(x-8+i*5,y-54+i*3,4,4);}}
 else if(f.visual==='hammerCrack'){c.fillStyle='#f1d399';for(let i=0;i<13;i++){px(x-38+i*6,y-3+(i%3)*3,7,3);px(x+(i%2?-1:1)*i*3,y-7-i*3-drift*10,3,4);}c.fillStyle='#fff0c2';px(x-6,y-37,12,34);}
 else if(f.visual==='eruption'){
  const seed=[...f.targetId].reduce((n,ch)=>(n*31+ch.charCodeAt(0))>>>0,0),phase=(seed%19)/19,grid=v=>Math.round(v/2)*2;
  // Deterministic display-only flame tongues: stepped taper, layered cores, no RNG.
  for(let i=0;i<5;i++){const baseX=x-22+i*11,variation=(seed>>>((i*5)%24))&15,h=22+variation*2+Math.sin((t*3+phase+i*.37)*Math.PI)*6,w=8+(i%2)*3;
   for(let row=0;row<h;row+=4){const z=row/h,sway=Math.sin(z*4+phase*6+i)*z*7,half=Math.max(1,grid(w*(1-z)**.8)),xx=grid(baseX+sway),yy=grid(y-row-4);
    c.fillStyle='#d84b2d';px(xx-half,yy,half*2,4);
    if(z<.84){const core=Math.max(2,grid(half*.64));c.fillStyle='#ff922f';px(xx-core,yy,core*2,4);}
    if(z<.52){const core=Math.max(1,grid(half*.28));c.fillStyle='#ffe684';px(xx-core,yy,core*2,4);}
   }
  }
  for(let i=0;i<16;i++){const a=i*Math.PI/8,rr=26+Math.sin(t*8+phase*4)*3;c.fillStyle=i%3?'#f37b36':'#ffd77b';px(grid(x+Math.cos(a)*rr),grid(y-1+Math.sin(a)*5),4,2);}
  for(let i=0;i<6;i++){const q=(phase+i*.163+t*.7)%1;c.fillStyle=i%2?'#ffcc61':'#f77930';px(grid(x-23+((seed+i*17)%47)),grid(y-22-q*45),2,2);}
 }
 else if(f.visual==='emberSeal'||f.visual==='emberTick'){const r=f.visual==='emberTick'?10:23;c.fillStyle='#ff8b42';for(let i=0;i<16;i++){const a=i*Math.PI/8;px(x+Math.cos(a)*r,y-54+Math.sin(a)*r,4,4);}c.fillStyle='#ffe5a0';px(x-2,y-68,4,28);px(x-12,y-57,24,4);px(x-8,y-65,4,4);px(x+5,y-47,4,4);}
 else if(f.visual==='ash'){for(let i=0;i<26;i++){c.fillStyle=['#a6a7a3','#767e83','#ccd0c5'][i%3];px(x-28+(i*13)%56+drift*(i%2?9:-9),y-75+(i*19)%53-drift*8,3+i%3,3);}}
 else if(f.visual==='poison'){c.fillStyle='#b8eb60';for(let i=0;i<5;i++)px(x-13+i*6,y-61-((i%2)*8)-drift*13,4,6);c.fillStyle='#6aab4c';px(x-8,y-40,17,3);}
 else if(f.visual==='shieldRune'){c.fillStyle='#82d9fb';for(let i=0;i<13;i++){px(x-24,y-78+i*4,3,4);px(x+22,y-78+i*4,3,4);}px(x-24,y-80,49,3);for(let i=0;i<7;i++){px(x-23+i*4,y-27+i*2,4,3);px(x+22-i*4,y-27+i*2,4,3);}c.fillStyle='#e3faff';px(x-2,y-69,4,30);px(x-11,y-58,22,4);}
 else if(f.visual==='healing'){c.fillStyle='#8eeda4';for(let i=0;i<12;i++){const xx=x-25+(i*17)%50,yy=y-15-(i*13)%60-drift*25;px(xx-2,yy,7,3);px(xx,yy-2,3,7);}}
 c.restore();
 }
}
export function createBattleSlicePresentation(positions,actorMetadata={},{preserveAttack=false}={}){const deferredHurts=new Map(),animations=new Map(),floats=[],effects=[],pending=[],seenAnimation=new Set(),lanes=new Map();animations.skillEffects=effects;return {animations,floats,effects,get deferredHurtCount(){return deferredHurts.size;},enqueue(events,at){const groups=new Map();for(const event of events){const key=event.castId+'|'+event.sourceId;if(!groups.has(key))groups.set(key,groups.size);const groupOffset=Math.min(650,groups.get(key)*100),hasDamage=events.some(x=>x.castId===event.castId&&x.sourceId===event.sourceId&&['hit','counter','legend'].includes(x.kind));pending.push({event:{...event,animateCast:hasDamage,actionElement:events.find(x=>x.castId===event.castId&&x.sourceId===event.sourceId&&['hit','counter','legend'].includes(x.kind))?.element??event.element},at:at+groupOffset+(event.displayDelayMs??event.segmentIndex*70)+(event.kind==='cast'?0:240)});}},advance(time){pending.sort((a,b)=>a.at-b.at);while(pending.length&&pending[0].at<=time){const {event,at}=pending.shift(),target=positions[event.targetId],source=positions[event.sourceId];if(!target)continue;const visual=skillVisualForEvent(event,actorMetadata[event.sourceId]?.weaponType);if(visual)effects.push({visual,targetId:event.targetId,sourceId:event.sourceId,segmentIndex:event.segmentIndex,skillId:event.skillId,at});const key=event.castId+event.sourceId;if(source&&(['hit','counter','legend'].includes(event.kind)||event.kind==='cast'&&event.animateCast)&&!seenAnimation.has(key)){seenAnimation.add(key);animations.set(event.sourceId,{kind:'attack',at,targetId:event.targetId,targetX:target.x,originX:source.x,element:event.actionElement??event.element,skillId:event.skillId});}if(event.hpDelta<0||event.shieldDelta<0){const active=animations.get(event.targetId);if(preserveAttack&&active?.kind==='attack'&&at-active.at<600)deferredHurts.set(event.targetId,active.at+600);else animations.set(event.targetId,{kind:'hurt',at});}const lane=lanes.get(event.targetId)??0;lanes.set(event.targetId,lane+1);displayTokens(event).forEach((token,i)=>floats.push({...token,x:target.x+(lane%2?9:-9),y:target.y-94-(lane%3)*15-i*15,at}));}for(const [targetId,at]of deferredHurts){if(!positions[targetId]){deferredHurts.delete(targetId);continue;}if(time<at)continue;const active=animations.get(targetId);if(active?.kind==='attack'&&time-active.at<600){deferredHurts.set(targetId,active.at+600);continue;}animations.set(targetId,{kind:'hurt',at});deferredHurts.delete(targetId);}for(let i=effects.length-1;i>=0;i--)if(time-effects[i].at>650)effects.splice(i,1);for(let i=floats.length-1;i>=0;i--)if(time-floats[i].at>1100)floats.splice(i,1);},clear(){animations.clear();deferredHurts.clear();floats.length=0;effects.length=0;pending.length=0;seenAnimation.clear();lanes.clear();}};}
export function presentationActorX(position,animation,time){if(animation?.kind!=='attack'||animation.element!=='physical'||!Number.isFinite(animation.targetX))return position.x;const elapsed=time-animation.at;if(elapsed<0||elapsed>=600)return position.x;const direction=Math.sign(animation.targetX-position.x)||1,contact=animation.targetX-direction*40;const progress=elapsed<180?elapsed/180:elapsed<340?1:1-(elapsed-340)/260;return position.x+(contact-position.x)*Math.max(0,Math.min(1,progress));}
export function battleSliceBars(encounter,positions,animations,time,{heroMaxHp,reduced=false}={}){
 const rows=[];for(const [id,p]of Object.entries(positions)){const u=id==='hero'?{hp:encounter.heroHp,max:heroMaxHp}:encounter.enemies.find(u=>u.id===id);if(!u||u.hp<=0||!(u.max>0))continue;
 const x=reduced?p.x:presentationActorX(p,animations.get(id),time),height=p.sprite==='lizard'?46:62;
 const shield=id==='hero'?readPlayerShieldRows(encounter).reduce((n,r)=>n+r.remaining,0):Math.max(0,u.shield??0);
 const bar={id,x,y:p.y-height-10,width:34,height:4,hp:Math.max(0,u.hp),max:u.max,shield,hpWidth:Math.min(1,Math.max(0,u.hp/u.max))*34,shieldWidth:Math.min(1,shield/u.max)*34};
 // Only separate coincident head bars, never change actor positions or combat.
 while(rows.some(r=>Math.abs(r.x-bar.x)<36&&Math.abs(r.y-bar.y)<6))bar.y-=7;
 rows.push(bar);
 }return rows;
}
export function drawBattleSliceBars(c,bars){for(const b of bars){const x=Math.round(b.x-b.width/2),y=Math.round(b.y);c.fillStyle='#0d171d';c.fillRect(x-1,y-1,b.width+2,b.height+2);c.fillStyle='#4d3838';c.fillRect(x,y,b.width,b.height);c.fillStyle=b.id==='hero'?'#75ab8d':'#bc665b';c.fillRect(x,y,b.hpWidth,b.height);if(b.shieldWidth>0){c.fillStyle='#b5e8f4';c.fillRect(x,y,b.shieldWidth,b.height);}}}
export function battleSpriteFrames(sprite,kind,skillId){const mapped=kind==='attack'?sprite.skillAnimations?.[skillId]:null;return sprite.animations[mapped??kind]??sprite.animations[kind]??sprite.animations.idle;}
// Facing describes the original PNG, not the actor's formation slot. Some authored
// animation frames turn independently; a frame override takes precedence.
export function battleSpriteFlipX(sprite,frame,actorX,targetX){
 const source=frame?.facing??sprite.facing;
 if(!['left','right'].includes(source)||!Number.isFinite(targetX)||targetX===actorX)return false;
 return source!==(targetX<actorX?'left':'right');
}
export function drawBattleSliceCanvas(canvas,{manifest,images,encounter,positions=slicePositions(encounter),animations=new Map(),time=0,reduced=false,floats=[],heroMaxHp=null,actorFrames={}}){const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,480,270);const areaKey=String(encounter.areaId??'dwarf.a01').match(/^(?:dwarf|human|elf|goblin|ashen)\.a\d+(?=\.|$)/)?.[0],backgroundIds=manifest.areaBackgrounds?.[areaKey],backgrounds=manifest.areaBackgrounds?manifest.backgrounds.filter(bg=>backgroundIds?.includes(bg.id)):manifest.backgrounds;for(const bg of backgrounds)c.drawImage(images.get(bg.file),0,0);for(const [id,p]of Object.entries(positions).sort((a,b)=>a[1].y-b[1].y)){const sprite=manifest.sprites[p.sprite],anim=animations.get(id),mode=!reduced&&anim&&time-anim.at<600?anim.kind:'idle',frames=battleSpriteFrames(sprite,mode,anim?.skillId);const index=mode==='idle'?Math.floor(time/500)%frames.length:Math.max(0,Math.min(frames.length-1,Math.floor((time-anim.at)/110)));const f=sprite.frames.find(f=>f.id===(actorFrames[id]??frames[index]));c.save();if(encounter.enemies.find(u=>u.id===id)?.hp<=0)c.globalAlpha=.35;const actorX=reduced?p.x:presentationActorX(p,anim,time),hero=positions.hero,heroX=hero?(reduced?hero.x:presentationActorX(hero,animations.get('hero'),time)):undefined;const targetX=id==='hero'?Object.entries(positions).find(([key])=>key!=='hero')?.[1]?.x??actorX+1:heroX;const flip=battleSpriteFlipX(sprite,f,actorX,targetX);c.translate(actorX,p.y);c.scale((flip?-1:1)*(p.scale??1),p.scale??1);c.drawImage(images.get(f.file),-sprite.anchor[0],-sprite.anchor[1]);c.restore();}for(const [id,anim]of animations){if(anim.kind!=='attack'||!anim.element||anim.element==='physical'||['ember_brand','furnace_wave','scatter_ash'].includes(anim.skillId))continue;const age=time-anim.at;if(age<60||age>390)continue;const source=positions[id],target=positions[anim.targetId];if(!source||!target)continue;const progress=Math.min(1,Math.max(0,(age-60)/200)),x=source.x+(target.x-source.x)*progress,y=source.y-65+Math.sin(progress*Math.PI)*-12;c.save();const color=DISPLAY_COLORS[anim.element]??'#ff9b54';c.fillStyle=color;if(progress<1){for(let i=0;i<5;i++){c.globalAlpha=1-i*.17;c.fillRect(Math.round(x-i*5*Math.sign(target.x-source.x)),Math.round(y-3+i%2),7-i,6-i*.5);}}else{c.globalAlpha=Math.max(0,1-(age-260)/130);for(let i=0;i<8;i++){const angle=i*Math.PI/4,r=5+(age-260)/10;c.fillRect(Math.round(target.x+Math.cos(angle)*r),Math.round(target.y-65+Math.sin(angle)*r),4,4);}}c.restore();}drawSkillEffects(c,animations.skillEffects??[],positions,time,reduced);drawBattleSliceBars(c,battleSliceBars(encounter,positions,animations,time,{heroMaxHp,reduced}));for(const f of floats){const age=time-f.at;if(age<0||age>1100)continue;c.save();c.globalAlpha=Math.min(1,(1100-age)/300);c.font=`bold ${f.crit?12:10}px monospace`;c.textAlign='center';c.lineWidth=2;const y=f.y-(reduced?0:age/30);drawCombatFloat(c,f,f.x,y);c.restore();}}
export async function mountBattleSlice(host,{assetRoot='./battle-assets/',scenario='fire'}={}){
 const response=await fetch(assetRoot+'manifest.json');if(!response.ok)throw Error('素材清单未就绪');const manifest=await response.json(),images=new Map();await Promise.all([...manifest.backgrounds,...Object.values(manifest.sprites).flatMap(s=>s.frames)].map(async f=>{const img=new Image();img.src=assetRoot+f.file;await img.decode();images.set(f.file,img);}));
 let model=createBattleSliceModel({scenario}),disposed=false,lastStep=0,raf=0,recorder=null;let position=slicePositions(model.encounter),presentation=createBattleSlicePresentation(position,sliceActorMetadata(model.state));const reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches??false;
 const get=id=>host.querySelector('#'+id);const reset=()=>{host.innerHTML=renderSliceShell(model);position=slicePositions(model.encounter);presentation=createBattleSlicePresentation(position,sliceActorMetadata(model.state));lastStep=0;};reset();const disposeConsumableErrors=bindConsumablePixelErrors(host);
 const enqueue=(events,at)=>presentation.enqueue(events,at);
 const hud=()=>{const s=model.state,e=model.encounter,max=E.stats(s).hp,enemyModels=normalizeBattleEnemies(e),units=[{id:'hero',name:s.hero,hp:e.heroHp,max},...e.enemies];get('sliceUnits').innerHTML=units.map(u=>{const p=position[u.id],shield=u.id==='hero'?readPlayerShieldRows(e).reduce((n,r)=>n+r.remaining,0):Math.max(0,u.shield??0);return `<div data-slice-unit="${esc(u.id)}" class="sliceUnit ${u.id==='hero'?'hero':'enemy'} ${e.targetId===u.id?'selected':''} ${u.hp<=0?'dead':''}" style="--x:${p.x/480*100}%"><div class="sliceUnitHud">${u.id!=='hero'?`<div class="sliceEffectStrip">${[...new Set(readEnemyEffectRows(e,u.id).map(r=>r.label+(r.layers?' '+r.layers:'')))].join(' · ')}</div>${enemyModels.find(m=>m.id===u.id)?.preparing?`<div class="sliceCastStrip">${esc(enemyModels.find(m=>m.id===u.id).preparing.name)}</div>`:''}`:''}</div>${u.id!=='hero'?`<button class="sliceTarget" title="${esc(u.name)} · ${Math.ceil(u.hp)}/${Math.ceil(u.max)}${shield?' · 护盾 '+Math.ceil(shield):''}" aria-label="选中${esc(u.name)}" data-slice-target="${esc(u.id)}" ${u.hp<=0?'disabled':''}></button>`:''}</div>`;}).join('');get('sliceRunLabel').textContent=s.running?'暂停':e.done?'已结束':'开始';get('sliceStatus').textContent=e.done?(e.win?'战斗胜利':'已撤退'):s.running?'交锋中':'已暂停';get('sliceSkills').innerHTML=skillButtons(s,e);get('slicePotionCount').textContent='药剂 '+(s.potionStacks?.['healing|0']??0);get('sliceOutcome').textContent=model.emissionError?'展示事件异常：'+model.emissionError:e.done?'本场结束 · 重开使用新的隔离角色':'点击敌人切换目标';get('sliceLog').innerHTML=model.logs.map(l=>'<p>'+esc(l)+'</p>').join('');};

 function frame(t){if(disposed)return;const now=Date.now();if(now-lastStep>=1100){lastStep=now;enqueue(model.advance(now),t);hud();}presentation.advance(t);drawBattleSliceCanvas(get('sliceCanvas'),{manifest,images,encounter:model.encounter,positions:position,animations:presentation.animations,time:t,reduced,floats:presentation.floats,heroMaxHp:E.stats(model.state).hp});for(const [id,p]of Object.entries(position)){const el=host.querySelector(`[data-slice-unit="${id}"]`);if(el)el.style.setProperty('--x',(reduced?p.x:presentationActorX(p,presentation.animations.get(id),t))/480*100+'%');}raf=requestAnimationFrame(frame);}
 const listener=ev=>{const b=ev.target.closest('button');if(!b||!host.contains(b))return;if(b.dataset.sliceTarget){model.select(b.dataset.sliceTarget);hud();return;}if(b.dataset.sliceSkill){const d=SKILL_TREE_DESCRIPTIONS[b.dataset.sliceSkill];get('sliceHelp').hidden=false;get('sliceHelp').innerHTML=`${renderSkillPixelIcon(b.dataset.sliceSkill,{size:64})}<b>${esc(names[b.dataset.sliceSkill])}</b><p>${esc(d?.base||'')}</p>`;return;}const action=b.dataset.sliceAction;if(action==='record'){if(recorder?.state==='recording'){recorder.stop();return;}const canvas=get('sliceCanvas');if(!canvas.captureStream||typeof MediaRecorder==='undefined'){get('sliceOutcome').textContent='此浏览器不支持场景录制';return;}const chunks=[];recorder=new MediaRecorder(canvas.captureStream(30));recorder.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data);};recorder.onstop=()=>{const url=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType||'video/webm'})),link=document.createElement('a');link.href=url;link.download='灰冠-战斗场景试作.webm';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);b.querySelector('span').textContent='录制场景';};recorder.start();b.querySelector('span').textContent='停止录制';return;}if(action==='toggle')model.toggle(Date.now());if(action==='potion')enqueue(model.drink(Date.now()).events,performance.now());if(action==='restart'){if(recorder?.state==='recording')recorder.stop();model.dispose();model=createBattleSliceModel({scenario});reset();}if(action==='log')get('sliceLog').hidden=!get('sliceLog').hidden;hud();};host.addEventListener('click',listener);hud();raf=requestAnimationFrame(frame);return {get model(){return model;},dispose(){disposed=true;if(recorder?.state==='recording')recorder.stop();cancelAnimationFrame(raf);model.dispose();disposeConsumableErrors();host.removeEventListener('click',listener);}};
}
